function coAnalyze(cfg){
  cfg=cfg||{};
  var origin=String(cfg.origin||'').trim();
  var cred=!!cfg.credentials;
  var problems=[], score=100;
  function warn(msg, penalty){ problems.push(msg); score-=penalty; }
  var wild=(origin==='*');
  var multi=origin.split(/\s+/).filter(Boolean).length>1;
  if(wild && cred) warn('Allow-Origin 为 * 时不允许携带凭证（浏览器将拒绝）', 40);
  if(multi) warn('Allow-Origin 出现多个空格分隔的值，标准仅允许单一来源或 *', 30);
  if(!origin) warn('未设置 Access-Control-Allow-Origin', 20);
  if(cred && !origin) warn('携带凭证但未指定具体来源', 15);
  if(!wild && !multi && origin) { /* specific origin is fine */ }
  score=Math.max(0, score);
  var grade = score>=90?'A':score>=70?'B':score>=50?'C':'D';
  return { wildcard:wild, multiple:multi, credentials:cred, score:score, problems:problems, level:(wild&&cred)?'危险':'正常', grade:grade };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { coAnalyze:coAnalyze };
}
if (typeof window !== 'undefined') {
  window.CorsForgePure = { coAnalyze:coAnalyze };
}
